$t['Automatic setup creates the webhook for this site URL only, or adds the missing events to it and keeps any other events. It saves the Webhook ID used to verify signatures. It never deletes webhooks, never touches other URLs and never changes the app permissions.'] = 'Automatisk opsætning opretter kun webhooken for dette websteds URL eller tilføjer de manglende hændelser til den og bevarer alle andre hændelser. Den gemmer det Webhook-ID, der bruges til at verificere signaturer. Den sletter aldrig webhooks, rører aldrig andre URL\'er og ændrer aldrig appens tilladelser.';
$t['Automatic setup needs Webhook Endpoints: Write. It creates the webhook and securely saves its new signing secret, or enables the existing endpoint and adds missing events. It preserves existing events and does not replace endpoints or change API key permissions.'] = 'Automatisk opsætning kræver Webhook Endpoints: Write. Den opretter webhooken og gemmer sikkert dens nye signeringshemmelighed, eller aktiverer det eksisterende endpoint og tilføjer manglende hændelser. Den bevarer eksisterende hændelser og erstatter ikke endpoints eller ændrer API-nøglens tilladelser.';
