$t['The commit identifies the Git revision checked out on this server; local file edits are not included. A Git tag is shown when one points directly to that commit.'] = 'Committen angiver den Git-revision, der er tjekket ud på denne server; lokale filændringer er ikke medtaget. Et Git-tag vises, når et tag peger direkte på den commit.';
$t['The Companion Chat service is not available right now. Ask your site administrator to check the AI plugin connection.'] = 'Companion Chat-tjenesten er ikke tilgængelig lige nu. Bed din webstedsadministrator om at tjekke AI-pluginnets forbindelse.';
$t['The connection could not be renewed. Please reconnect your account.'] = 'Forbindelsen kunne ikke fornys. Forbind din konto igen.';
$t['The connection expired and could not be renewed. Please reconnect your account.'] = 'Forbindelsen er udløbet og kunne ikke fornys. Forbind din konto igen.';
$t['The connection to the destination was dropped mid-stream. This may be a temporary network issue; FFMPEG will try to reconnect.'] = 'Forbindelsen til destinationen blev afbrudt under streamen. Det kan være et midlertidigt netværksproblem; FFMPEG vil forsøge at genoprette forbindelsen.';
$t['The connection to YouTube was interrupted. The upload was paused and can be resumed.'] = 'Forbindelsen til YouTube blev afbrudt. Uploaden blev sat på pause og kan genoptages.';
$t['The connection was interrupted. Check your account before retrying this subscription.'] = 'Forbindelsen blev afbrudt. Tjek din konto, før du prøver dette abonnement igen.';
$t['The connection was renewed.'] = 'Forbindelsen blev fornyet.';
$t['The connection window was closed before the authorization finished. No account was connected.'] = 'Forbindelsesvinduet blev lukket, før godkendelsen var fuldført. Ingen konto blev forbundet.';
$t['The converted files were kept. Contact the site administrator to retry the transfer; you do not need to upload the video again.'] = 'De konverterede filer blev bevaret. Kontakt webstedsadministratoren for at prøve overførslen igen; du behøver ikke at uploade videoen igen.';
$t['The converted video could not be sent back to this site.'] = 'Den konverterede video kunne ikke sendes tilbage til dette websted.';
$t['The customers of the selected card. Search, sort, copy the e-mails or export everything to a spreadsheet.'] = 'Kunderne for det valgte kort. Søg, sorter, kopier e-mailadresserne, eller eksporter det hele til et regneark.';
$t['The daily YouTube upload quota of this website was reached. Uploads become available again after midnight Pacific Time. Please try again later.'] = 'Dette websteds daglige YouTube-uploadkvote er nået. Uploads bliver tilgængelige igen efter midnat Pacific Time. Prøv igen senere.';
$t['The database version changes only when a database migration is applied. It is not expected to match the release tag or commit.'] = 'Databaseversionen ændres kun, når en databasemigrering anvendes. Den forventes ikke at matche release-tagget eller committen.';
$t['The default'] = 'Standardindstillingen';
$t['The destination RTMP server refused the connection. Check the stream URL and make sure the server is online.'] = 'Destinationens RTMP-server afviste forbindelsen. Tjek stream-URL\'en, og sørg for, at serveren er online.';
$t['The destination server requires authentication. Check the stream key.'] = 'Destinationsserveren kræver godkendelse. Tjek streamnøglen.';
$t['The destination server returned 403. The stream key may be invalid or expired.'] = 'Destinationsserveren returnerede 403. Streamnøglen kan være ugyldig eller udløbet.';
$t['The destination video was removed or this account cannot edit it. Check the video and account access on the site.'] = 'Destinationsvideoen er fjernet, eller denne konto kan ikke redigere den. Tjek videoen og kontoadgangen på webstedet.';
$t['The download is controlled by the system, there is nothing to check on the user'] = 'Downloadet styres af systemet, der er intet at kontrollere brugeren';
$t['The download permission is site wide, so there is nothing to check on the video'] = 'Downloadtilladelsen er bred på webstedet, så der er ikke noget at kontrollere på videoen';
$t['The download permission is site wide, so there is nothing to check onthe video'] = 'The download permission is site wide, so there is nothing to check onthe video';
$t['The email is invalid'] = 'E-mailen er ugyldig';
$t['The encoder could not download the original file.'] = 'Encoderen kunne ikke downloade den originale fil.';
$t['The encoder could not find this video on the site.'] = 'Encoderen kunne ikke finde denne video på webstedet.';
$t['The encoder did not confirm that the video was added to the queue. Please retry.'] = 'Encoderen bekræftede ikke, at videoen blev føjet til køen. Prøv igen.';
$t['The encoder is running out of disk space'] = 'Encoderen er ved at løbe tør for diskplads';
$t['The encoder reported an unexpected error.'] = 'Encoderen rapporterede en uventet fejl.';
$t['The encoding process stopped unexpectedly, and the automatic retries also failed.'] = 'Kodningsprocessen stoppede uventet, og de automatiske genforsøg mislykkedes også.';
$t['The encoding queue is stalled'] = 'Kodningskøen står stille';
$t['The event purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'Købet af eventet kunne ikke gennemføres. Din wallet-betaling blev ikke trukket. Tjek din saldo, før du prøver igen.';
$t['The file could not be converted. It may be damaged or use a format the encoder does not support.'] = 'Filen kunne ikke konverteres. Den kan være beskadiget eller bruge et format, som encoderen ikke understøtter.';
$t['The file must be an .vtt file!'] = 'The file must be an .vtt file!';
$t['The file must be an .vtt or .srt file!'] = 'Filen skal være en .vtt- eller .srt-fil!';
$t['The final charge uses the duration measured during processing. A connected Marketplace wallet is required.'] = 'Den endelige opkrævning bruger den varighed, der blev målt under behandlingen. En forbundet Marketplace-wallet er påkrævet.';
$t['The following movie contains materials that are not suitable for children 17 and under.'] = 'Følgende film indeholder materiale, der ikke er egnet til børn på 17 år og derunder.';
$t['The following movie contains materials that may not be suitable for children 17 and under.'] = 'Følgende film indeholder materiale, der muligvis ikke er egnet til børn på 17 år og derunder.';
$t['The form to signup will not exists'] = 'Formularen til tilmelding findes ikke';
$t['The gift code has been canceled. If this is unexpected, please contact our support team.'] = 'Gavekoden er blevet annulleret. Hvis dette er uventet, bedes du kontakte vores supportteam.';
$t['The gift code is currently inactive. Please check back later or contact support.'] = 'Gavekoden er i øjeblikket inaktiv. Prøv igen senere, eller kontakt support.';
$t['The information above corresponds to our official records and confirms the authenticity of this certificate.'] = 'Oplysningerne ovenfor svarer til vores officielle registreringer og bekræfter ægtheden af dette certifikat.';
$t['The input stream contains invalid data. The source HLS may not be ready yet or the stream was interrupted.'] = 'Inputstreamen indeholder ugyldige data. Kilde-HLS\'en er muligvis ikke klar endnu, eller streamen blev afbrudt.';
$t['The installed PHP package lists both fixes, but this web process still runs the copy loaded before the update. Restart Apache or PHP-FPM.'] = 'Den installerede PHP-pakke indeholder begge rettelser, men denne webproces kører stadig den kopi, der blev indlæst før opdateringen. Genstart Apache eller PHP-FPM.';
