$t['There is no Pay Per View plan yet. Create one in the Pay-Per-View plugin, PPV Plans tab.'] = 'Der er endnu ingen Pay Per View-plan. Opret en i Pay-Per-View-pluginnet under fanen PPV-planer.';
$t['There is no plan that can hold videos yet. Create one in the PPV Plans tab, then come back here.'] = 'Der er endnu ingen plan, der kan indeholde videoer. Opret en under fanen PPV-planer, og vend derefter tilbage hertil.';
$t['There is no streaming now'] = 'Der er ingen streaming nu';
$t['The release number and the AVideo database version are independent. Code update status is determined by commit history.'] = 'Udgivelsesnummeret og AVideo-databaseversionen er uafhængige af hinanden. Status for kodeopdatering bestemmes ud fra commit-historikken.';
$t['The request to the social network failed. Please try again later.'] = 'Anmodningen til det sociale netværk mislykkedes. Prøv igen senere.';
$t['The restreamer server cannot reach the destination. Check network connectivity.'] = 'Restreamer-serveren kan ikke nå destinationen. Tjek netværksforbindelsen.';
$t['The same alert is repeated at most every %s while the problem continues.'] = 'Den samme advarsel gentages højst hver %s, så længe problemet fortsætter.';
$t['The same alert is repeated at most every few hours while the problem continues.'] = 'Den samme advarsel gentages højst med få timers mellemrum, så længe problemet fortsætter.';
$t['The selected camera or microphone is not available. Please choose another device.'] = 'Det valgte kamera eller den valgte mikrofon er ikke tilgængelig. Vælg en anden enhed.';
$t['The selected position is highlighted on a real page. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'Den valgte position fremhæves på en rigtig side. Mobilforhåndsvisning ændrer kun annoncepositionerne; resten af siden bruger din browsers enhed.';
$t['The selected position is outlined on a real page of your site and follows the position you choose below. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'Den valgte placering er markeret på en rigtig side på dit websted og følger den placering, du vælger nedenfor. Mobilforhåndsvisning ændrer kun annonceplaceringerne; resten af siden bruger din browsers enhed.';
$t['The server is not ready'] = 'Serveren er ikke klar';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = 'Siden er i øjeblikket offline på grund af et databaseproblem. Vi arbejder på at løse problemet så hurtigt som muligt.';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'Siden er midlertidigt utilgængelig, fordi serverens disk er fuld. Vi arbejder på problemet og er snart tilbage.';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'Siden er under vedligeholdelse, da serverens disk er ved at være fuld. Vi arbejder på problemet og er snart tilbage.';
$t['The site refused access. Renew the encoder account access and check its upload permissions.'] = 'Siden nægtede adgang. Forny encoder-kontoens adgang, og tjek dens upload-tilladelser.';
$t['The site will display only a login form to un authenticated users'] = 'Webstedet viser kun en loginformular til uautentificerede brugere';
$t['The source stream ended. If the live was stopped intentionally this is normal.'] = 'Kildestreamen sluttede. Hvis livestreamen blev stoppet med vilje, er dette normalt.';
$t['The split is on: desktop visitors do not see this banner now, they see the left and right halves.'] = 'Opdelingen er slået til: Besøgende på computer ser ikke dette banner nu, de ser venstre og højre halvdel.';
$t['The stream has timestamp discontinuities. This can cause buffering or playback issues on the destination platform.'] = 'Streamen har afbrydelser i tidsstemplerne. Dette kan give buffering eller afspilningsproblemer på destinationsplatformen.';
$t['The subtitle has not been copied to the player yet.'] = 'Underteksten er endnu ikke kopieret til afspilleren.';
$t['The subtitle is already on the player.'] = 'Underteksten er allerede på afspilleren.';
$t['The subtitle was copied to the player.'] = 'Underteksten blev kopieret til afspilleren.';
$t['The subtitle will be available when processing finishes.'] = 'Underteksten vil være tilgængelig, når behandlingen er færdig.';
