$t['YouTube: Google only lists channels you own or manage as a Brand Account. If your channel is not listed, fill in its stream URL and stream key by hand in the form.'] = 'YouTube: Google viser kun kanaler, som du ejer eller administrerer som en brandkonto. Hvis din kanal ikke vises, skal du udfylde dens stream-URL og streamnøgle manuelt i formularen.';
$t['YouTube accepts up to 100 characters.'] = 'YouTube accepterer op til 100 tegn.';
$t['YouTube accepts up to 5000 characters. HTML is removed.'] = 'YouTube accepterer op til 5000 tegn. HTML fjernes.';
$t['YouTube and other supported video links download through your own connection, which can help when a provider blocks the Encoder server.'] = 'YouTube og andre understøttede videolinks downloades via din egen forbindelse, hvilket kan hjælpe, når en udbyder blokerer Encoder-serveren.';
$t['YouTube category'] = 'YouTube-kategori';
$t['YouTube could not process the uploaded file. Check that the video plays correctly on this site and publish it again.'] = 'YouTube kunne ikke behandle den uploadede fil. Kontrollér, at videoen afspilles korrekt på dette websted, og udgiv den igen.';
$t['YouTube Data API'] = 'Din opdatering fra fil% s er færdig, klik på Fortsæt';
$t['YouTube Data API Overview'] = 'Din brugerkonto er oprettet!';
$t['YouTube did not accept the description. Edit the description and publish again.'] = 'YouTube accepterede ikke beskrivelsen. Redigér beskrivelsen, og udgiv igen.';
$t['YouTube did not accept the selected category. Choose another category and publish again.'] = 'YouTube accepterede ikke den valgte kategori. Vælg en anden kategori, og udgiv igen.';
$t['YouTube did not accept the selected privacy setting. Choose another one and publish again.'] = 'YouTube accepterede ikke den valgte privatlivsindstilling. Vælg en anden, og udgiv igen.';
$t['YouTube did not accept the tags. Edit the tags and publish again.'] = 'YouTube accepterede ikke tags. Redigér tags, og udgiv igen.';
$t['YouTube did not accept the title. Edit the title and publish again.'] = 'YouTube accepterede ikke titlen. Redigér titlen, og udgiv igen.';
$t['YouTube did not accept the video details. Check the title, description and tags, then publish again.'] = 'YouTube accepterede ikke videooplysningerne. Kontrollér titel, beskrivelse og tags, og udgiv derefter igen.';
$t['YouTube did not allow this upload. Reconnect your YouTube account and allow this website to manage your YouTube videos.'] = 'YouTube tillod ikke denne upload. Forbind din YouTube-konto igen, og giv dette websted tilladelse til at administrere dine YouTube-videoer.';
$t['YouTube is receiving too many requests right now. Please wait a few minutes and try again.'] = 'YouTube modtager for mange anmodninger lige nu. Vent et par minutter, og prøv igen.';
$t['YouTube rejected the video because it does not follow the YouTube policies.'] = 'YouTube afviste videoen, fordi den ikke overholder YouTubes retningslinjer.';
$t['YouTube rejected the video because it is a duplicate of a video already on your channel.'] = 'YouTube afviste videoen, fordi den er en kopi af en video, der allerede findes på din kanal.';
$t['YouTube rejected the video because it is longer than your channel allows. Verify your YouTube account to upload longer videos.'] = 'YouTube afviste videoen, fordi den er længere, end din kanal tillader. Bekræft din YouTube-konto for at uploade længere videoer.';
$t['YouTube rejected the video because of a copyright claim.'] = 'YouTube afviste videoen på grund af et krav om ophavsret.';
$t['YouTube returned an unexpected error. Please try again later. If the problem continues, contact the site administrator.'] = 'YouTube returnerede en uventet fejl. Prøv igen senere. Hvis problemet fortsætter, skal du kontakte webstedets administrator.';
$t['YouTube URL'] = 'YouTube-URL';
$t['You were disconnected because your account was used to log in from another device or location'] = 'Du blev afbrudt, fordi din konto blev brugt til at logge ind fra en anden enhed eller et andet sted';
